import{_ as t,c as n,o,ae as a}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Text Element","description":"Text Element","frontmatter":{"title":"Text Element","description":"Text Element"},"headers":[],"relativePath":"guide/drag-drop-elements/text-element.md","filePath":"guide/drag-drop-elements/text-element.md"}'),l={name:"guide/drag-drop-elements/text-element.md"};function r(s,e,i,d,h,m){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="text-element" tabindex="-1">Text Element <a class="header-anchor" href="#text-element" aria-label="Permalink to &quot;Text Element&quot;">​</a></h1><p>A table is used to visualize data, and texts carry the primary data of any table. After knowing how to create the <a href="https://ninjatables.com/docs/how-to-create-your-first-drag-and-drop-table-with-ninja-tables/" target="_blank" rel="noreferrer">first drag-and-drop table</a> you should be clear about all the elements of this module. In this guide, we will explore the <strong>Text</strong> element, a free element available in the builder. As you engage with the Editor Box, you&#39;ll find seamless text editing access at your fingertips. Let’s add a Text element to our Ninja Tables! <img src="https://ninjatables.com/wp-content/uploads/2023/08/Drag-cell-element-1024x453.png" alt="Drag cell element and drop on table"> All you need to do is drag the element from the left menu and drop it on the table.</p><h2 id="properties-of-text-elements" tabindex="-1"><strong>Properties of Text Element</strong>s <a class="header-anchor" href="#properties-of-text-elements" aria-label="Permalink to &quot;**Properties of Text Element**s&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Scope</strong></th><th><strong>Option Name</strong></th><th><strong>Type</strong></th></tr></thead><tbody><tr><td>Text Options</td><td>Font Color</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Font Size</td><td>Numeric Value</td></tr><tr><td></td><td>Alignment</td><td>Left, Center, Right</td></tr><tr><td></td><td>Font Weight</td><td>Bold, Italic, Underline</td></tr><tr><td><img src="https://ninjatables.com/wp-content/uploads/2023/08/Customize-table-cell-element-1024x583.png" alt="Customize table cell element"></td><td></td><td></td></tr></tbody></table><h3 id="customize-text-elements-in-tables" tabindex="-1">Customize Text Elements in Tables <a class="header-anchor" href="#customize-text-elements-in-tables" aria-label="Permalink to &quot;Customize Text Elements in Tables&quot;">​</a></h3><ul><li><strong>Editor Box:</strong> You can edit the text of the Text Element. (Or, type in the cell)</li><li><strong>Font Color</strong>: You can change the color of the text. By default, it is set to Black.</li><li><strong>Font Size</strong>: Change the size of the text. By default, it is set to 15.</li><li>**Alignment: **You can align texts to the left, right, or center. By default, it is set to Center.</li><li><strong>Font Style</strong>: You can change the Font Style orientations. Available options are <strong>Bold</strong>, <em>Italic</em>, and Underline.</li></ul><h2 id="conclusion" tabindex="-1"><strong>Conclusion</strong> <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;**Conclusion**&quot;">​</a></h2><p>We hope this documentation on Text Element has helped you understand the functionality of this Ninja Tables Drag &amp; Drop Table Builder element. Please check our other documentation regarding the features of the Drag &amp; Drop Tables and create WordPress tables effortlessly with Ninja Tables! Let us know your thoughts and questions in the comment box below.</p>',8)])])}const g=t(l,[["render",r]]);export{u as __pageData,g as default};
